// R1P-02: owner AUTHORSHIP and external CONTENT are two trust cases and
// must not share one class. Case A carries owner instruction authority;
// Case B carries NONE and may inform classification only.
// Embedded external content inside a Case A idea is classified separately.
return items.map(i => {
  const ownerAuthored = i.json.origin === 'owner' && Boolean(i.json.owner_authenticated);
  return { json: {
    envelope: { trust: 'external-untrusted', partition: 'business',
                source: ownerAuthored ? 'owner-surface' : 'import',
                received_at: new Date().toISOString(),
                links_followed: false, attachments_opened: false },
    origin: ownerAuthored ? 'owner' : 'external',
    // embedded external material inside an owner-authored idea keeps its
    // own class — quoting something does not authorise it
    embedded_external_present: Boolean(i.json.quoted_content),
    metadata: { subject: i.json.subject, project: i.json.project ?? null },
    restricted_content: { body: i.json.body ?? null },
    content_forwarded: Boolean(i.json.body)
  } };
});

// The R1P-02 proof obligation, asserted rather than assumed. A future edit
// that let an external note carry instruction authority fails here.
for (const i of items) {
  const origin = i.json.origin, auth = i.json.instruction_authority;
  if (origin === 'external' && auth !== 'none') {
    throw new Error('R1P-02 violated: external origin acquired authority ' + auth);
  }
  if ((i.json.actions_taken || []).length) {
    throw new Error('POC-2 takes no external action');
  }
}
return items;
